147	function showConfigStatus() {
148	  const local = {
149	    exists: Config.hasLocalApiKey(),
150	    value: Config.getLocalApiKey()
151	  };
152	  const global = {
153	    exists: Config.hasGlobalApiKey(),
154	    value: Config.getGlobalApiKey()
155	  };
156	
157	  const status = {
158	    local: {
159	      configured: local.exists,
160	      location: LOCAL_ENV_DISPLAY
161	    },
162	    global: {
163	      configured: global.exists,
164	      location: GLOBAL_CONFIG_DISPLAY
165	    }
166	  };
167	
168	  log.info('API key configuration status', status);
169	  if (local.exists) {
170	    log.info('Local API key detected (masked).');
171	  }
172	  if (global.exists) {
173	    log.info('Global API key detected (masked).');
174	  }
175	  if (!local.exists && !global.exists) {
176	    log.warn('No OpenAI API key configured. Some AI powered features will be unavailable.');
177	  }
178	}
