477	function runEvalCommand(options: EvalOptions) {
478	  assertFileExists(options.outputs);
479	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
480	    outputsPath: options.outputs,
481	    referencesPath: options.references
482	  });
483	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
484	    outputs: dataset.outputs,
485	    references: dataset.references
486	  });
487	
488	  let thresholds: Record<string, number> | undefined;
489	  if (options.threshold && options.threshold.length > 0) {
490	    const parseResult = (Eval.parseThresholds as unknown as (strs: string[]) => any)(options.threshold);
491	    if (!parseResult.valid) {
492	      log.error(parseResult.error);
493	      process.exit(2);
494	    }
495	
496	    const validateResult = (Eval.validateThresholds as unknown as (thresh: unknown, metrics: unknown) => any)(
497	      parseResult.thresholds,
498	      evaluations
499	    );
500	    if (!validateResult.valid) {
501	      log.error(validateResult.error);
502	      process.exit(2);
503	    }
504	
505	    thresholds = parseResult.thresholds;
506	  }
507	
508	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
509	    evaluations,
510	    outputsPath: dataset.outputsPath,
511	    referencesPath: dataset.referencesPath,
512	    thresholds
513	  });
514	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
515	    report,
516	    format: options.format ?? 'json',
517	    reportPath: options.report
518	  });
519	  log.success('Evaluation report generated.', { path: resolvedPath });
520	
521	  if (thresholds && !report.passed) {
