import fs from 'fs';
import os from 'os';
import path from 'path';

import { Eval } from './packages/frai-core/src/index.js';

const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-test-'));

try {
  // Create test data
  const outputsPath = path.join(tmpDir, 'outputs.json');
  const referencesPath = path.join(tmpDir, 'references.json');

  fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World', 'Test'], null, 2));
  fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world', 'test'], null, 2));

  // Load data
  const dataset = Eval.loadDataset({ outputsPath, referencesPath });
  console.log('✓ Dataset loaded');

  // Run evaluations
  const evaluations = Eval.runEvaluations({
    outputs: dataset.outputs,
    references: dataset.references
  });
  console.log('✓ Evaluations ran');
  console.log('  Metrics:', evaluations.map((m) => `${m.id}=${m.score}`).join(', '));

  // Test threshold parsing
  const parseResult = Eval.parseThresholds(['exact_match=0.9', 'toxicity=0.95']);
  console.log('✓ Thresholds parsed:', parseResult.thresholds);

  // Test threshold validation
  const validResult = Eval.validateThresholds(parseResult.thresholds, evaluations);
  if (validResult.valid) {
    console.log('✓ Thresholds validated');
  } else {
    console.log('✗ Threshold validation failed:', validResult.error);
  }

  // Test with passing thresholds
  const passingThresholds = { exact_match: 0.5 };
  const reportPassing = Eval.generateReport({
    evaluations,
    outputsPath,
    referencesPath,
    thresholds: passingThresholds
  });
  console.log('✓ Report with passing thresholds generated');
  console.log('  Report passed:', reportPassing.passed);
  console.log('  Threshold results:', reportPassing.thresholds);

  // Test with failing thresholds
  const failingThresholds = { exact_match: 0.99 };
  const reportFailing = Eval.generateReport({
    evaluations,
    outputsPath,
    referencesPath,
    thresholds: failingThresholds
  });
  console.log('✓ Report with failing thresholds generated');
  console.log('  Report passed:', reportFailing.passed);
  console.log('  Threshold results:', reportFailing.thresholds);

  // Test markdown report with thresholds
  const markdownPath = path.join(tmpDir, 'report.md');
  Eval.writeReport({
    report: reportPassing,
    format: 'markdown',
    reportPath: markdownPath
  });
  const markdown = fs.readFileSync(markdownPath, 'utf8');
  console.log('✓ Markdown report written');
  if (markdown.includes('## Thresholds')) {
    console.log('  ✓ Thresholds section found in markdown');
  } else {
    console.log('  ✗ Thresholds section NOT found in markdown');
  }

  // Test JSON report with thresholds
  const jsonPath = path.join(tmpDir, 'report.json');
  Eval.writeReport({
    report: reportPassing,
    format: 'json',
    reportPath: jsonPath
  });
  const json = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
  console.log('✓ JSON report written');
  if (json.passed !== undefined && json.thresholds !== undefined) {
    console.log('  ✓ Thresholds fields found in JSON');
  } else {
    console.log('  ✗ Thresholds fields NOT found in JSON');
  }

  // Test error cases
  console.log('\n✓ Testing error cases:');

  // Invalid format
  const invalidFormat = Eval.parseThreshold('invalid:format');
  console.log('  Invalid format:', invalidFormat.valid === false ? '✓ Caught' : '✗ Not caught');

  // Value out of range
  const outOfRange = Eval.parseThreshold('metric=1.5');
  console.log('  Out of range:', outOfRange.valid === false ? '✓ Caught' : '✗ Not caught');

  // Unknown metric
  const unknownMetric = Eval.validateThresholds({ unknown: 0.5 }, evaluations);
  console.log('  Unknown metric:', unknownMetric.valid === false ? '✓ Caught' : '✗ Not caught');

  // Null score with threshold
  const evaluationsWithNull = [
    { id: 'test_metric', score: null }
  ];
  const evalResult = Eval.evaluateThresholds({ test_metric: 0.5 }, evaluationsWithNull);
  console.log('  Null score fails threshold:', evalResult.passed === false ? '✓ Correct' : '✗ Incorrect');

  console.log('\n✅ All tests passed!');
} finally {
  // Cleanup
  fs.rmSync(tmpDir, { recursive: true, force: true });
}

