1	export function parseThreshold(thresholdStr) {
2	  const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
3	  if (!match) {
4	    return {
5	      valid: false,
6	      error: `Invalid threshold format: "${thresholdStr}". Expected format: <metric>=<number>`
7	    };
8	  }
9	  const [, metricId, minStr] = match;
10	  const min = parseFloat(minStr);
11	  if (isNaN(min) || min < 0 || min > 1) {
12	    return {
13	      valid: false,
14	      error: `Threshold value for "${metricId}" must be a number between 0 and 1, got "${minStr}"`
15	    };
16	  }
17	  return {
18	    valid: true,
19	    metricId,
20	    min
21	  };
22	}
23	
24	export function parseThresholds(thresholdStrs = []) {
25	  const thresholds = {};
26	  for (const str of thresholdStrs) {
27	    const parsed = parseThreshold(str);
28	    if (!parsed.valid) {
29	      return { valid: false, error: parsed.error };
30	    }
31	    thresholds[parsed.metricId] = parsed.min;
32	  }
33	  return { valid: true, thresholds };
34	}
35	
36	export function validateThresholds(thresholds, metrics) {
37	  const validMetricIds = new Set(metrics.map((m) => m.id));
38	  const errors = [];
39	  for (const metricId of Object.keys(thresholds)) {
40	    if (!validMetricIds.has(metricId)) {
41	      errors.push(metricId);
42	    }
43	  }
44	  if (errors.length > 0) {
45	    const validIds = Array.from(validMetricIds).sort();
46	    return {
47	      valid: false,
48	      error: `Unknown metric id: ${errors.join(', ')}. Valid ids are: ${validIds.join(', ')}`
49	    };
50	  }
51	  return { valid: true };
52	}
53	
54	export function evaluateThresholds(thresholds, metrics) {
55	  const results = [];
56	  let allPassed = true;
57	
58	  for (const [metricId, min] of Object.entries(thresholds)) {
59	    const metric = metrics.find((m) => m.id === metricId);
60	    if (!metric) {
61	      continue;
62	    }
63	    const score = metric.score;
64	    const passed = score !== null && score >= min;
65	    if (!passed) {
66	      allPassed = false;
67	    }
68	    results.push({
69	      metric: metricId,
